package com.aerialcue;

import com.google.inject.Provides;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Projectile;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.api.kit.KitType;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Aerial Cue",
	description = "Plays a countdown of audio cues while your bird is away aerial fishing",
	tags = {"aerial", "fishing", "hunter", "sound", "audio", "cue", "tick"}
)
public class AerialCuePlugin extends Plugin
{
	/** Number of clips a sound profile provides. Cue N plays when N-1 ticks remain. */
	static final int MAX_CUE_TICKS = 5;

	/**
	 * Ticks you must wait before the next spot can be clicked, by distance between you and the spot.
	 * Distances outside this range never produce a catch worth cueing.
	 */
	private static final Map<Integer, Integer> DISTANCE_TO_TICKS = new HashMap<>();

	static
	{
		DISTANCE_TO_TICKS.put(1, 0);
		DISTANCE_TO_TICKS.put(2, 0);
		DISTANCE_TO_TICKS.put(3, 1);
		DISTANCE_TO_TICKS.put(4, 1);
		DISTANCE_TO_TICKS.put(5, 2);
		DISTANCE_TO_TICKS.put(6, 3);
		DISTANCE_TO_TICKS.put(7, 3);
		DISTANCE_TO_TICKS.put(8, 4);
		DISTANCE_TO_TICKS.put(9, 4);
		DISTANCE_TO_TICKS.put(10, 5);
	}

	/** A frenzied (large) spot always takes the same time regardless of distance. */
	private static final int FRENZIED_TICKS = 2;

	@Inject
	private Client client;

	@Inject
	private AerialCueConfig config;

	@Inject
	private CueSoundPlayer soundPlayer;

	/** Tick on which each tracked catch becomes clickable again. */
	private final Map<Projectile, Integer> readyTicks = new HashMap<>();

	/** Centre tiles of frenzied spots currently in the scene. */
	private final Set<WorldPoint> frenziedPoints = new HashSet<>();

	private final Set<Projectile> seen = new HashSet<>();

	@Override
	protected void startUp()
	{
		soundPlayer.start();
		soundPlayer.load(config.soundProfile());
	}

	@Override
	protected void shutDown()
	{
		soundPlayer.stop();
		readyTicks.clear();
		frenziedPoints.clear();
		seen.clear();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// NPCs and projectiles do not survive a scene load, so drop everything tied to the old scene.
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			readyTicks.clear();
			frenziedPoints.clear();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (AerialCueConfig.GROUP.equals(event.getGroup()) && "soundProfile".equals(event.getKey()))
		{
			soundPlayer.load(config.soundProfile());
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		WorldPoint centre = frenziedCentre(event.getNpc());
		if (centre != null)
		{
			frenziedPoints.add(centre);
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		WorldPoint centre = frenziedCentre(event.getNpc());
		if (centre != null)
		{
			frenziedPoints.remove(centre);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!isGloveEquipped())
		{
			readyTicks.clear();
			return;
		}

		trackProjectiles();

		int tick = client.getTickCount();
		int soonest = Integer.MAX_VALUE;

		for (Integer readyTick : readyTicks.values())
		{
			int remaining = readyTick - tick;
			if (remaining >= 0 && remaining < soonest)
			{
				soonest = remaining;
			}
		}

		// Cue 1 lands on the tick the spot is clickable again, cue 2 the tick before it, and so on.
		int cue = soonest + 1;

		// One cue per tick, for whichever catch lands first, so overlapping catches cannot stack sounds.
		if (soonest != Integer.MAX_VALUE && cue <= Math.min(config.countdownTicks(), MAX_CUE_TICKS))
		{
			soundPlayer.play(cue, config.volume(), config.humanizeGain(), config.humanizePitch());
		}
	}

	/**
	 * Registers any newly thrown bird and retires spent catches.
	 */
	private void trackProjectiles()
	{
		Player local = client.getLocalPlayer();
		seen.clear();

		for (Projectile projectile : client.getProjectiles())
		{
			if (projectile.getId() != SpotanimID.AERIAL_FISHING_TRAVEL || projectile.getTargetActor() != local)
			{
				continue;
			}

			seen.add(projectile);

			if (readyTicks.containsKey(projectile))
			{
				continue;
			}

			// Registration happens on the tick the projectile is created, so the distance is measured
			// before the player has had a chance to move. The projectile's own remaining flight is not
			// a substitute: the bird is still in the air after the spot becomes clickable again.
			int waitTicks = waitTicks(projectile);

			if (waitTicks < 0)
			{
				continue;
			}

			int readyTick = client.getTickCount() + waitTicks;
			readyTicks.put(projectile, readyTick);

			log.debug("Catch registered: wait {} ticks, ready on tick {} ({} cycles of flight left)",
				waitTicks, readyTick, projectile.getRemainingCycles());
		}

		// An entry outlives its own projectile so a countdown always finishes, and is only dropped once
		// the projectile is gone, which is what stops a long-lived projectile being registered twice.
		int tick = client.getTickCount();
		readyTicks.entrySet().removeIf(entry -> tick > entry.getValue() && !seen.contains(entry.getKey()));
		seen.clear();
	}

	/**
	 * Ticks to wait before the spot is clickable again. Returns -1 for a distance that never produces
	 * a catch worth cueing.
	 */
	private int waitTicks(Projectile projectile)
	{
		WorldPoint source = projectile.getSourcePoint();

		if (frenziedPoints.contains(source))
		{
			return FRENZIED_TICKS;
		}

		return DISTANCE_TO_TICKS.getOrDefault(source.distanceTo2D(projectile.getTargetPoint()), -1);
	}

	/**
	 * The centre tile of a frenzied spot, matching the point its projectiles are thrown from, or null
	 * if the NPC is not a frenzied spot.
	 */
	private WorldPoint frenziedCentre(NPC npc)
	{
		if (npc.getId() != NpcID.FISHING_SPOT_AERIAL_LARGE)
		{
			return null;
		}

		int offset = npc.getComposition().getSize() / 2;
		return npc.getWorldLocation().dx(offset).dy(offset);
	}

	private boolean isGloveEquipped()
	{
		Player local = client.getLocalPlayer();
		if (local == null || local.getPlayerComposition() == null)
		{
			return false;
		}

		int weaponId = local.getPlayerComposition().getEquipmentId(KitType.WEAPON);
		return weaponId == ItemID.AERIAL_FISHING_GLOVES_BIRD || weaponId == ItemID.AERIAL_FISHING_GLOVES_NO_BIRD;
	}

	@Provides
	AerialCueConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AerialCueConfig.class);
	}
}

package com.aerialcue;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadLocalRandom;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

/**
 * Holds a {@link SoundProfile}'s clips in memory, ready to fire.
 *
 * Cues have to land on the game tick that scheduled them, so playback cannot afford to read a wav
 * off the classpath first: inflating it out of the jar is prone to stalling, which is audible
 * against a 600ms tick. Every clip is therefore read into a byte array once, up front and off the
 * client thread, leaving playback as a handoff to {@link AudioPlayer} on the audio thread.
 *
 * Fired verbatim, a cue is the same bytes at the same level thousands of times an hour, and exact
 * repetition wears on the ear independently of how pleasant the sound is. Two optional nudges break
 * it: a random gain offset per play, and a random pick from detuned copies of each clip built at
 * load time. Both are sized to sit under what a listener notices as a change.
 */
@Slf4j
@Singleton
class CueSoundPlayer
{
	/** Random gain offset per cue, in dB either side of the configured volume. Level JND is about 1 dB. */
	private static final float GAIN_HUMANIZE_DB = 1f;

	/**
	 * Copies of each clip per cue, index 0 being the untouched original and the rest spread evenly
	 * across ±{@link #PITCH_HUMANIZE_CENTS}. Pitch JND for a complex tone is 5-10 cents; the cues sit
	 * 200 cents apart at their closest, so the countdown's notes cannot be confused for one another.
	 */
	private static final int PITCH_VARIANTS = 7;
	private static final double PITCH_HUMANIZE_CENTS = 4;

	/** Field offsets in a canonical 44-byte PCM wav header. */
	private static final int WAV_HEADER_LENGTH = 44;
	private static final int WAV_SAMPLE_RATE = 24;
	private static final int WAV_BYTE_RATE = 28;
	private static final int WAV_BLOCK_ALIGN = 32;

	@Inject
	private AudioPlayer audioPlayer;

	/** Opening a line blocks, so playback never happens on the client thread. */
	private ExecutorService executor;

	/**
	 * Raw wav data for the loaded profile, indexed by cue number minus one and then by pitch variant.
	 * Null entries failed to load; a clip whose header could not be detuned has only its original.
	 */
	private volatile byte[][][] samples;
	private SoundProfile requested;

	/** Variant last played per cue, so the same waveform never fires twice in a row. Client thread only. */
	private final int[] lastVariant = new int[AerialCuePlugin.MAX_CUE_TICKS];

	/** Set once the mixer refuses a detuned clip's sample rate, after which only originals are played. */
	private volatile boolean pitchUnsupported;

	void start()
	{
		pitchUnsupported = false;
		executor = Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "aerial-cue-audio");
			t.setDaemon(true);
			return t;
		});
	}

	void stop()
	{
		samples = null;
		requested = null;

		if (executor != null)
		{
			executor.shutdownNow();
			executor = null;
		}
	}

	void load(SoundProfile profile)
	{
		if (profile == requested || executor == null)
		{
			return;
		}

		requested = profile;

		executor.execute(() ->
		{
			samples = null;

			byte[][][] loaded = new byte[AerialCuePlugin.MAX_CUE_TICKS][][];
			for (int i = 0; i < loaded.length; i++)
			{
				String path = "/sounds/" + profile.getDirectory() + "/tick_" + (i + 1) + ".wav";
				try (InputStream in = CueSoundPlayer.class.getResourceAsStream(path))
				{
					if (in == null)
					{
						log.warn("Missing cue sound {}", path);
						continue;
					}

					loaded[i] = variants(readFully(in));
				}
				catch (Exception e)
				{
					log.warn("Unable to load cue sound {}", path, e);
				}
			}

			samples = loaded;
			log.debug("Loaded sound profile {}", profile);
		});
	}

	/**
	 * Fires the given cue at a linear 0-100 volume. Safe to call from the client thread.
	 *
	 * @param humanizeGain  nudge the level by up to ±{@link #GAIN_HUMANIZE_DB}
	 * @param humanizePitch play a random detuned copy instead of the same waveform every time
	 */
	void play(int cue, int volume, boolean humanizeGain, boolean humanizePitch)
	{
		byte[][][] current = samples;
		ExecutorService executor = this.executor;

		if (current == null || executor == null || volume <= 0 || cue < 1 || cue > current.length)
		{
			return;
		}

		byte[][] variants = current[cue - 1];
		if (variants == null)
		{
			return;
		}

		int variant = 0;
		if (humanizePitch && variants.length > 1 && !pitchUnsupported)
		{
			// Draw from every variant but the one this cue played last.
			int last = lastVariant[cue - 1];
			variant = ThreadLocalRandom.current().nextInt(variants.length - 1);
			if (variant >= last)
			{
				variant++;
			}
			lastVariant[cue - 1] = variant;
		}

		byte[] sample = variants[variant];
		byte[] original = variants[0];

		// Matches the client's own notification volume curve: linear 1-100 to decibel gain.
		float gain = (float) Math.log10(Math.min(volume, 100) / 100f) * 20f;

		if (humanizeGain)
		{
			// Never above 0 dB: MASTER_GAIN rejects values past its range, and AudioPlayer answers that
			// by playing at full volume, ignoring the setting entirely. Mirroring the offset rather than
			// clamping it keeps a full-volume cue varying instead of pinning half its plays to exactly 0.
			float jitter = (ThreadLocalRandom.current().nextFloat() * 2f - 1f) * GAIN_HUMANIZE_DB;
			gain = gain + jitter > 0 ? gain - jitter : gain + jitter;
		}

		float finalGain = gain;

		try
		{
			executor.execute(() ->
			{
				try
				{
					audioPlayer.play(new ByteArrayInputStream(sample), finalGain);
					return;
				}
				catch (Exception e)
				{
					if (sample == original)
					{
						log.warn("Unable to play cue {}", cue, e);
						return;
					}

					log.debug("Mixer rejected detuned cue {}", cue, e);
				}

				// A mixer that will not open a line at the detuned rate would otherwise silence the cue.
				// If the original plays, the rate was the problem, and there is no point asking again.
				try
				{
					audioPlayer.play(new ByteArrayInputStream(original), finalGain);
					pitchUnsupported = true;
					log.warn("Mixer rejected detuned cue sounds; pitch variation disabled for this session");
				}
				catch (Exception e)
				{
					log.warn("Unable to play cue {}", cue, e);
				}
			});
		}
		catch (Exception e)
		{
			log.debug("Dropped cue {}", cue, e);
		}
	}

	/**
	 * The original clip followed by its detuned copies, or the original alone if its header is not
	 * one {@link #detune} understands.
	 */
	private static byte[][] variants(byte[] original)
	{
		byte[][] variants = new byte[PITCH_VARIANTS][];
		variants[0] = original;

		for (int i = 1; i < PITCH_VARIANTS; i++)
		{
			// Evenly spaced from -max to +max, skipping 0 since index 0 already is the original.
			double cents = -PITCH_HUMANIZE_CENTS + 2 * PITCH_HUMANIZE_CENTS * (i - 1) / (PITCH_VARIANTS - 2);
			byte[] detuned = detune(original, cents);

			if (detuned == null)
			{
				return new byte[][]{original};
			}

			variants[i] = detuned;
		}

		return variants;
	}

	/**
	 * A copy of a PCM wav whose header claims a sample rate the given number of cents away from the
	 * original. The sample data is untouched: the decoder plays it faster or slower, which shifts
	 * pitch and length together. A few cents moves the length by well under a millisecond, so the
	 * cue still lands on its tick.
	 *
	 * Only the canonical 44-byte layout is handled, which is what the generator writes. Returns null
	 * for anything else rather than guessing at where the rate field is.
	 */
	private static byte[] detune(byte[] wav, double cents)
	{
		if (wav.length <= WAV_HEADER_LENGTH)
		{
			return null;
		}

		ByteBuffer header = ByteBuffer.wrap(wav).order(ByteOrder.LITTLE_ENDIAN);
		boolean canonical = header.getInt(0) == 0x46464952 // "RIFF"
			&& header.getInt(8) == 0x45564157 // "WAVE"
			&& header.getInt(12) == 0x20746d66 // "fmt "
			&& header.getInt(16) == 16 // PCM fmt chunk, so the data chunk starts at 36
			&& header.getShort(20) == 1; // uncompressed

		if (!canonical)
		{
			return null;
		}

		int rate = header.getInt(WAV_SAMPLE_RATE);
		int blockAlign = header.getShort(WAV_BLOCK_ALIGN);
		int detunedRate = (int) Math.round(rate * Math.pow(2, cents / 1200));

		byte[] copy = wav.clone();
		ByteBuffer.wrap(copy).order(ByteOrder.LITTLE_ENDIAN)
			.putInt(WAV_SAMPLE_RATE, detunedRate)
			.putInt(WAV_BYTE_RATE, detunedRate * blockAlign);
		return copy;
	}

	private static byte[] readFully(InputStream in) throws Exception
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		byte[] buffer = new byte[8192];

		for (int read; (read = in.read(buffer)) != -1; )
		{
			out.write(buffer, 0, read);
		}

		return out.toByteArray();
	}
}

package com.aerialcue;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * A set of five countdown sounds bundled with the plugin.
 *
 * Each profile is a directory under {@code /sounds} containing {@code tick_1.wav} through
 * {@code tick_5.wav}, where {@code tick_N} is played when N ticks remain before the fishing
 * spot can be clicked again. To add a profile, drop a new directory of five wavs into
 * {@code src/main/resources/sounds} and add a constant here.
 */
@Getter
@RequiredArgsConstructor
public enum SoundProfile
{
	TONE("Tone", "tone"),
	MARIMBA("Marimba", "marimba"),
	KALIMBA("Kalimba", "kalimba"),
	LOG_DRUM("Log drum", "logdrum"),
	GLASS("Glass", "glass"),
	PLUCK("Pluck", "pluck"),
	/** Deliberately longer than a game tick, so consecutive cues ring over one another. */
	PLUCK_LONG("Pluck (long)", "plucklong"),
	GUITAR("Guitar chords", "guitar"),
	DRUMPAD("Drum pad", "drumpad"),
	SUB_808("808", "sub808");

	private final String displayName;
	private final String directory;

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.aerialcue;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(AerialCueConfig.GROUP)
public interface AerialCueConfig extends Config
{
	String GROUP = "aerial-cue";

	@ConfigItem(
		position = 0,
		keyName = "soundProfile",
		name = "Sound profile",
		description = "Which set of countdown sounds to play."
	)
	default SoundProfile soundProfile()
	{
		return SoundProfile.MARIMBA;
	}

	@ConfigItem(
		position = 1,
		keyName = "countdownTicks",
		name = "Countdown length",
		description = "How many cues to play, counting back from the tick the spot is clickable again. At 5 a"
			+ " full-distance catch plays all five; at 1 only the cue on the tick you can click plays."
	)
	@Range(min = 1, max = AerialCuePlugin.MAX_CUE_TICKS)
	@Units(Units.TICKS)
	default int countdownTicks()
	{
		return AerialCuePlugin.MAX_CUE_TICKS;
	}

	@ConfigItem(
		position = 2,
		keyName = "volume",
		name = "Volume",
		description = "Playback volume of the countdown sounds."
	)
	@Range(max = 100)
	@Units(Units.PERCENT)
	default int volume()
	{
		return 100;
	}

	@ConfigItem(
		position = 3,
		keyName = "humanizeGain",
		name = "Vary volume slightly",
		description = "Randomly varies each cue's volume by an inaudible amount, so exact repeats don't wear on"
			+ " your ears over a long session."
	)
	default boolean humanizeGain()
	{
		return true;
	}

	@ConfigItem(
		position = 4,
		keyName = "humanizePitch",
		name = "Vary pitch slightly",
		description = "Randomly varies each cue's pitch by an inaudible amount, so exact repeats don't wear on"
			+ " your ears over a long session."
	)
	default boolean humanizePitch()
	{
		return true;
	}
}
